  "anotacoes": [
    {
      "trecho_id": "ACTION_LOG.A1",
      "rotulo": "CORRETO",
      "informacoes": [],
      "observacao": "A entrega do redutor em D20 continua definindo o início da montagem."
    },
    {
      "trecho_id": "ACTION_LOG.A2",
      "rotulo": "REVISAR",
      "informacoes": [
        {
          "citacao": "dentro da franquia de 10 dias (R$ 20.000,00)",
          "motivo": "premissa_alterada",
          "correto_seria": "Os testes ocupam 12 dias, de D25 a D37: excedem a franquia em 2 dias, gerando R$ 1.000,00 adicionais e custo laboratorial total de R$ 21.000,00."
        }
      ],
      "observacao": "O protótipo continua disponível em D25, mas a validação passa a terminar em D37."
    },
    {
      "trecho_id": "ACTION_LOG.A3",
      "rotulo": "CORRETO",
      "informacoes": [],
      "observacao": "A mudança na duração do teste de vida não altera o desenho CAD revisão 1 nem sua geração."
    },
    {
      "trecho_id": "ACTION_LOG.A4",
      "rotulo": "REVISAR",
      "informacoes": [
        {
          "citacao": "a ser preenchido entre D35 e D38",
          "motivo": "valor_divergente",
          "correto_seria": "A documentação passa a ser preenchida entre D37 e D40."
        },
        {
          "citacao": "protótipo disponível em D24",
          "motivo": "valor_divergente",
          "correto_seria": "O protótipo fica disponível em D25."
        },
        {
          "citacao": "validação concluída em D35",
          "motivo": "valor_divergente",
          "correto_seria": "A validação é concluída em D37."
        }
      ],
      "observacao": "A data D24 do protótipo já divergia do estado inicial; a mudança no teste de vida desloca a validação e a documentação em dois dias."
    },
    {
      "trecho_id": "RISK_REGISTER.R1",
      "rotulo": "REVISAR",
      "informacoes": [
        {
          "citacao": "Liberação de engenharia (D40)",
          "motivo": "valor_divergente",
          "correto_seria": "A Liberação de engenharia passa a ocorrer em D42."
        }
      ],
      "observacao": "O redutor continua no caminho crítico, sem folga. A taxa de R$ 300,00 por dia além de D40 permanece aplicável."
    },
    {
      "trecho_id": "RISK_REGISTER.R2",
      "rotulo": "REVISAR",
      "informacoes": [
        {
          "citacao": "pode ultrapassar os 10 dias previstos",
          "motivo": "premissa_alterada",
          "correto_seria": "O teste de vida passou a durar 12 dias, excedendo em 2 dias a franquia de 10."
        }
      ],
      "observacao": "A validação termina em D37 e o excedente gera R$ 1.000,00 de cobrança laboratorial."
    },
    {
      "trecho_id": "RISK_REGISTER.R3",
      "rotulo": "CORRETO",
      "informacoes": [],
      "observacao": "A folga da fornecedora da placa e do chicote permanece em 1 dia."
    },
    {
      "trecho_id": "RISK_REGISTER.R4",
      "rotulo": "CORRETO",
      "informacoes": [],
      "observacao": "A mudança no teste de vida não altera as afirmações verificáveis sobre o risco de vedação; a confiança da equipe é uma opinião."
    },
    {
      "trecho_id": "DECISION_LOG.D1",
      "rotulo": "PRESERVAR",
